type FitnessHTTPClient interface {
	AbandonChallenge(ctx context.Context, req *request.AbandonChallengeRequest, opts ...http.CallOption) (rsp *response.AbandonChallengeResponse, err error)
	CancelRedemption(ctx context.Context, req *request.CancelRedemptionRequest, opts ...http.CallOption) (rsp *response.CancelRedemptionResponse, err error)
	// CreateCompetition Admin only.
	CreateCompetition(ctx context.Context, req *request.CreateCompetitionRequest, opts ...http.CallOption) (rsp *response.CreateCompetitionResponse, err error)
	// EndWalkSession Finalizes the session, runs the full anti-cheat pass and credits points.
	EndWalkSession(ctx context.Context, req *request.EndWalkSessionRequest, opts ...http.CallOption) (rsp *response.EndWalkSessionResponse, err error)
	GetCompetition(ctx context.Context, req *request.GetCompetitionRequest, opts ...http.CallOption) (rsp *response.GetCompetitionResponse, err error)
	// GetDailyQuota Remaining attempts, step cap and cooldown for today, so the app can
	// disable the start button instead of provoking a rejection.
	GetDailyQuota(ctx context.Context, req *request.GetDailyQuotaRequest, opts ...http.CallOption) (rsp *response.GetDailyQuotaResponse, err error)
	GetGift(ctx context.Context, req *request.GetGiftRequest, opts ...http.CallOption) (rsp *response.GetGiftResponse, err error)
	// GetLeaderboard Serves competition, weekly, monthly and all-time boards at any scope.
	GetLeaderboard(ctx context.Context, req *request.GetLeaderboardRequest, opts ...http.CallOption) (rsp *response.GetLeaderboardResponse, err error)
	GetMyPointsBalance(ctx context.Context, req *request.GetMyPointsBalanceRequest, opts ...http.CallOption) (rsp *response.GetMyPointsBalanceResponse, err error)
	GetMyProfile(ctx context.Context, req *request.GetMyProfileRequest, opts ...http.CallOption) (rsp *response.GetMyProfileResponse, err error)
	GetMyStats(ctx context.Context, req *request.GetMyStatsRequest, opts ...http.CallOption) (rsp *response.GetMyStatsResponse, err error)
	// GetRegionStandings District-vs-district or state-vs-state standings.
	GetRegionStandings(ctx context.Context, req *request.GetRegionStandingsRequest, opts ...http.CallOption) (rsp *response.GetRegionStandingsResponse, err error)
	GetWalkSession(ctx context.Context, req *request.GetWalkSessionRequest, opts ...http.CallOption) (rsp *response.GetWalkSessionResponse, err error)
	JoinCompetition(ctx context.Context, req *request.JoinCompetitionRequest, opts ...http.CallOption) (rsp *response.JoinCompetitionResponse, err error)
	LeaveCompetition(ctx context.Context, req *request.LeaveCompetitionRequest, opts ...http.CallOption) (rsp *response.LeaveCompetitionResponse, err error)
	ListChallengeTemplates(ctx context.Context, req *request.ListChallengeTemplatesRequest, opts ...http.CallOption) (rsp *response.ListChallengeTemplatesResponse, err error)
	ListCompetitions(ctx context.Context, req *request.ListCompetitionsRequest, opts ...http.CallOption) (rsp *response.ListCompetitionsResponse, err error)
	ListFlaggedSessions(ctx context.Context, req *request.ListFlaggedSessionsRequest, opts ...http.CallOption) (rsp *response.ListFlaggedSessionsResponse, err error)
	ListGifts(ctx context.Context, req *request.ListGiftsRequest, opts ...http.CallOption) (rsp *response.ListGiftsResponse, err error)
	ListMyChallenges(ctx context.Context, req *request.ListMyChallengesRequest, opts ...http.CallOption) (rsp *response.ListMyChallengesResponse, err error)
	ListMyPointsLedger(ctx context.Context, req *request.ListMyPointsLedgerRequest, opts ...http.CallOption) (rsp *response.ListMyPointsLedgerResponse, err error)
	ListMyRedemptions(ctx context.Context, req *request.ListMyRedemptionsRequest, opts ...http.CallOption) (rsp *response.ListMyRedemptionsResponse, err error)
	ListMyWalkSessions(ctx context.Context, req *request.ListMyWalkSessionsRequest, opts ...http.CallOption) (rsp *response.ListMyWalkSessionsResponse, err error)
	// ListRegions States, or a state's districts, for the onboarding pickers.
	ListRegions(ctx context.Context, req *request.ListRegionsRequest, opts ...http.CallOption) (rsp *response.ListRegionsResponse, err error)
	// RedeemGift Reserves the points immediately; fulfilment moves it to FULFILLED or
	// refunds on rejection.
	RedeemGift(ctx context.Context, req *request.RedeemGiftRequest, opts ...http.CallOption) (rsp *response.RedeemGiftResponse, err error)
	ReviewSession(ctx context.Context, req *request.ReviewSessionRequest, opts ...http.CallOption) (rsp *response.ReviewSessionResponse, err error)
	// StartChallenge Consumes one of the day's attempts. Fails with CHALLENGE_DAILY_LIMIT_REACHED
	// once the cap is hit, and is idempotent on idempotency_key.
	StartChallenge(ctx context.Context, req *request.StartChallengeRequest, opts ...http.CallOption) (rsp *response.StartChallengeResponse, err error)
	StartWalkSession(ctx context.Context, req *request.StartWalkSessionRequest, opts ...http.CallOption) (rsp *response.StartWalkSessionResponse, err error)
	// SubmitWalkSamples Called every 30-60s while walking. The server recomputes distance and steps
	// from the samples; client totals are never trusted.
	SubmitWalkSamples(ctx context.Context, req *request.SubmitWalkSamplesRequest, opts ...http.CallOption) (rsp *response.SubmitWalkSamplesResponse, err error)
	UpsertMyProfile(ctx context.Context, req *request.UpsertMyProfileRequest, opts ...http.CallOption) (rsp *response.UpsertMyProfileResponse, err error)
}

